  "pa-ch3-004": { question: "The top major crash type for 16 year old drivers in Pennsylvania is:", choices: ["Single vehicle/run-off-the-road", "Being sideswiped on an interstate", "Driving in reverse on a side street", "Driving on the shoulder of a highway"], explanation: "The manual identifies single-vehicle / run-off-the-road crashes as the main crash type for 16-year-old Pennsylvania drivers." },
  "pa-ch3-005": { question: "When passing a bicyclist, you should:", choices: ["Blast your horn to alert the bicyclist", "Move as far left as possible", "Remain in the center of the lane", "Put on your four-way flashers"], explanation: "When passing a bicycle rider, move as far left as you safely can to leave plenty of space." },
  "pa-ch3-006": { question: "When you drive through an area where children are playing, you should expect them:", choices: ["To know when it is safe to cross", "To stop at the curb before crossing the street", "To run out in front of you without looking", "Not to cross unless they are with an adult"], explanation: "Near children at play, expect them to run out in front of you without looking; slow down and be ready." },
  "pa-ch3-007": { question: "If you are driving behind a motorcycle, you must:", choices: ["Allow the motorcycle to use a complete lane", "Drive on the shoulder beside the motorcycle", "Allow the motorcycle to use only half a lane", "Pass in the same lane where the motorcycle is driving"], explanation: "A motorcycle must be allowed to use a full lane; never crowd it by sharing the lane." },
