  "pa-ch3-035": { question: "If a vehicle using high beams comes toward you, you should:", choices: ["Turn on your high beams", "Turn off your headlights", "Sound your horn", "Flash your high beams"], explanation: "If an oncoming driver has high beams on, flash your high beams once to remind them to dim theirs." },
  "pa-ch3-036": { question: "If a vehicle using high beams comes toward you, you should look towards _____of the road.", choices: ["Either side", "The center", "The right side", "The left side"], explanation: "When blinded by oncoming high beams, keep toward the right side of the road and avoid looking into the lights." },
